#!/usr/bin/env bash
# Scenario "without-claude": only the claude-code Feature, with Claude Code's install skipped
# (CI doesn't download it). The agent must bring the Panem base along by itself. Run with:
#   devcontainer features test --project-folder features --features claude-code --skip-autogenerated
set -e
# shellcheck disable=SC1091
source dev-container-features-test-lib
check "base installed by the agent" test -x /usr/local/share/panem/post-create.sh
check "base version recorded" test -s /usr/local/share/panem/VERSION
check "relay installed" test -x /usr/local/share/panem/relay-conn.sh
check "agent registered" test -f /usr/local/share/panem/agents/claude-code/agent.json
check "agent hooks" test -x /usr/local/share/panem/agents/claude-code/start.sh
check "agent options" grep -q PANEM_REMOTE_CONTROL=true /usr/local/share/panem/agents/claude-code/agent.env
check "code root writable" test -w /codebase
check "tmux" command -v tmux
check "jq" command -v jq
check "socat" command -v socat
# shellcheck disable=SC2016 # $HOME expands inside bash -c, on purpose
check "claude skipped" bash -c '! command -v claude && ! test -e "$HOME/.local/bin/claude"'
reportResults
